177	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
178	    @Override
179	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
180	        List<String> missingFields = new ArrayList<>();
181	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
182	            missingFields.add("firstName");
183	        }
184	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
185	            missingFields.add("lastName");
186	        }
187	        // Normalize the address up front; the required-field check rejects it when it is blank
188	        // after normalization (e.g. a whitespace-only value collapses to the empty string).
189	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
190	        if (!StringUtils.hasText(normalizedAddress)) {
191	            missingFields.add("address");
192	        }
193	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
194	            missingFields.add("city");
195	        }
196	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
197	            missingFields.add("telephone");
198	        }
199	        if (!missingFields.isEmpty()) {
200	            throw new InvalidRequestException(missingFields);
201	        }
202	        HttpHeaders headers = new HttpHeaders();
203	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
204	        // Store (and later return) the normalized address computed above.
205	        owner.setAddress(normalizedAddress);
206	        // Normalize the telephone into E.164 form (reject with 400 when it cannot form a valid one).
207	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
208	        owner.setTelephone(normalizedTelephone);
209	        // Normalize the (optional) email: reject a syntactically invalid address, otherwise store it lower-cased.
210	        owner.setEmail(normalizeEmail(owner.getEmail()));
211	        // Validate the (optional) postcode: reject with 400 when present but malformed or out of range
212	        // for the city's region. The value (mapped straight from the request) is stored and returned as given.
213	        validatePostcode(owner.getCity(), owner.getPostcode());
214	        // Default the (optional) registration date to the server's current date when none was supplied.
215	        if (owner.getRegistrationDate() == null) {
216	            owner.setRegistrationDate(LocalDate.now());
217	        }
218	        // The effective registration date must fall on a business day: when it lands on a Saturday or
219	        // Sunday (whether supplied or defaulted above), roll it forward to the next Monday. Every value
220	        // derived from the registration date below (daily create-limit, membership number) uses this
221	        // adjusted date.
222	        owner.setRegistrationDate(rollToBusinessDay(owner.getRegistrationDate()));
223	        // Reject the request once the maximum number of owners for the owner's registration day has
224	        // been reached (100 or more owners already created on that date).
225	        int ownersRegisteredToday = countOwnersRegisteredOn(owner.getRegistrationDate());
226	        if (ownersRegisteredToday >= MAX_OWNERS_PER_DAY) {
227	            throw new DailyOwnerLimitException(owner.getRegistrationDate());
228	        }
229	        // Flag a bulk-signup warning when more than 80 owners had already been created on this
230	        // owner's registration day at the moment this owner was created; otherwise clear it.
231	        owner.setBulkSignupWarning(ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD);
232	        // Reject the request when the owner's city has already reached its owner capacity.
233	        if (countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
234	            throw new CityCapacityException(owner.getCity());
235	        }
236	        // Resolve household membership before computing the identity key: when another owner already
237	        // shares the same last name and address (compared case-insensitively with collapsed
238	        // whitespace) and the caller opts in by setting 'sharesHousehold' true, assign a stable
239	        // shared 'householdId' to the new owner and backfill it onto every existing member that does
240	        // not yet carry it. The household is thus reflected in the owner's identity key.
241	        List<Owner> householdMembers = findHouseholdMembers(owner.getLastName(), owner.getAddress());
242	        if (!householdMembers.isEmpty() && Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
243	            String householdId = generateHouseholdId(owner.getLastName(), owner.getAddress());
244	            owner.setHouseholdId(householdId);
245	            for (Owner member : householdMembers) {
246	                if (!householdId.equals(member.getHouseholdId())) {
247	                    member.setHouseholdId(householdId);
248	                    this.clinicService.saveOwner(member);
249	                }
250	            }
251	        }
252	        // All duplicate detection is consolidated into this single derived identity key
253	        // ('<normalizedTelephone>|<email or empty>|<householdId or empty>'): reject with 409 only
254	        // when the new owner's WHOLE identity key exactly matches an existing owner's. Because the
255	        // telephone is part of the key, two members of the same household with different telephones
256	        // have different keys and are both allowed; only an exact full-key match is a duplicate.
257	        String identityKey = owner.getIdentityKey();
258	        boolean identityCollision = this.clinicService.findAllOwners().stream()
259	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
260	        if (identityCollision) {
261	            throw new DuplicateIdentityException(identityKey);
262	        }
263	        // Record how many existing owners already share this first name and last name
264	        // (compared case-insensitively) before this owner is created.
265	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
266	        // Assign the customer code '<CITY3>-<LAST3>-<NNNN>' before persisting.
267	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
268	        // Assign the membership number '<customerCode>-M<YY>' where YY is the last two
269	        // digits of the registration date year (e.g. 'SYD-SMI-0007-M26').
270	        owner.setMembershipNumber(generateMembershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
271	        this.clinicService.saveOwner(owner);
272	        populateHouseholdSize(owner);
273	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
274	        // Emit an audit line carrying the new owner's id, customer code, registration date
275	        // and numeric membership level.
276	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
277	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
278	            ownerDto.getMembershipLevel());
279	        headers.setLocation(UriComponentsBuilder.newInstance()
280	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
281	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
282	    }
283	
284	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
285	    @Override
286	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
287	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
288	        if (currentOwner == null) {
289	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
290	        }
291	        currentOwner.setAddress(ownerFieldsDto.getAddress());
292	        currentOwner.setCity(ownerFieldsDto.getCity());
293	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
294	        currentOwner.setLastName(ownerFieldsDto.getLastName());
295	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
296	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
297	        this.clinicService.saveOwner(currentOwner);
298	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
299	    }
300	
301	    /**
302	     * Populate the owner's household size: the number of owners sharing this owner's
303	     * {@code householdId} (including the owner itself). An owner with no household is a household
304	     * of one.
305	     *
306	     * @param owner the owner whose household size should be computed and set
307	     */
308	    private void populateHouseholdSize(Owner owner) {
309	        String householdId = owner.getHouseholdId();
310	        if (!StringUtils.hasText(householdId)) {
311	            owner.setHouseholdSize(1);
312	            return;
313	        }
314	        int size = (int) this.clinicService.findAllOwners().stream()
315	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
316	            .count();
317	        owner.setHouseholdSize(size);
318	    }
319	
320	    /**
321	     * Generate a customer code formatted {@code <CITY3>-<LAST3>-<NNNN>}, where {@code CITY3} is the
322	     * upper-cased first three letters of {@code city}, {@code LAST3} is the upper-cased first three
323	     * letters of {@code lastName} and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to
324	     * one more than the current number of owners already in that city (e.g. {@code SYD-SMI-0007}).
325	     *
326	     * @param city     the owner's city
327	     * @param lastName the owner's last name
328	     * @return the generated customer code
329	     */
330	    private String generateCustomerCode(String city, String lastName) {
331	        String cityPrefix = city.length() >= 3 ? city.substring(0, 3) : city;
332	        String lastPrefix = lastName.length() >= 3 ? lastName.substring(0, 3) : lastName;
333	        String normalizedCity = normalizeForComparison(city);
334	        int sequence = (int) this.clinicService.findAllOwners().stream()
335	            .filter(existing -> normalizeForComparison(existing.getCity()).equals(normalizedCity))
336	            .count() + 1;
337	        return String.format("%s-%s-%04d", cityPrefix.toUpperCase(Locale.ROOT),
338	            lastPrefix.toUpperCase(Locale.ROOT), sequence);
339	    }
340	
341	    /**
342	     * Roll a registration date forward onto a business day: a Saturday or Sunday is advanced to the
343	     * following Monday, while a weekday is returned unchanged. This is the effective registration date
344	     * that is stored, returned and used for every value derived from it.
345	     *
346	     * @param date the effective registration date (supplied or defaulted)
347	     * @return the same date when it is a weekday, otherwise the next Monday
348	     */
349	    private LocalDate rollToBusinessDay(LocalDate date) {
350	        DayOfWeek dayOfWeek = date.getDayOfWeek();
351	        if (dayOfWeek == DayOfWeek.SATURDAY) {
352	            return date.plusDays(2);
353	        }
354	        if (dayOfWeek == DayOfWeek.SUNDAY) {
355	            return date.plusDays(1);
356	        }
357	        return date;
358	    }
359	
360	    /**
361	     * Generate a membership number formatted {@code <customerCode>-M<YY>}, where {@code YY} is the
362	     * last two digits of the {@code registrationDate} year (e.g. {@code SYD-SMI-0007-M26}).
363	     *
364	     * @param customerCode     the owner's already-assigned customer code
365	     * @param registrationDate the owner's registration date
366	     * @return the generated membership number
367	     */
368	    private String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
369	        String yy = String.format("%02d", registrationDate.getYear() % 100);
370	        return String.format("%s-M%s", customerCode, yy);
371	    }
372	
373	    /**
374	     * Count the existing owners that share the given first name and last name, comparing each
375	     * case-insensitively (trimmed, with internal whitespace collapsed). The incoming owner is not
376	     * yet persisted, so it is not included in the count.
377	     *
378	     * @param firstName the incoming owner's first name
379	     * @param lastName  the incoming owner's last name
380	     * @return the number of existing namesakes
381	     */
382	    private int countNamesakes(String firstName, String lastName) {
383	        String normalizedFirstName = normalizeForComparison(firstName);
384	        String normalizedLastName = normalizeForComparison(lastName);
385	        return (int) this.clinicService.findAllOwners().stream()
386	            .filter(existing -> normalizeForComparison(existing.getFirstName()).equals(normalizedFirstName)
387	                && normalizeForComparison(existing.getLastName()).equals(normalizedLastName))
388	            .count();
389	    }
390	
391	    /**
392	     * Count the existing owners whose city matches the given city, comparing case-insensitively with
393	     * collapsed whitespace. The incoming owner is not yet persisted, so it is not included in the count.
394	     *
395	     * @param city the incoming owner's city
396	     * @return the number of existing owners already in that city
397	     */
398	    private int countOwnersInCity(String city) {
399	        String normalizedCity = normalizeForComparison(city);
400	        return (int) this.clinicService.findAllOwners().stream()
401	            .filter(existing -> normalizeForComparison(existing.getCity()).equals(normalizedCity))
402	            .count();
403	    }
404	
405	    /**
406	     * Count the existing owners whose registration date equals the given date. The incoming owner is
407	     * not yet persisted, so it is not included in the count.
408	     *
409	     * @param registrationDate the incoming owner's registration date
410	     * @return the number of existing owners already registered on that date
411	     */
412	    private int countOwnersRegisteredOn(LocalDate registrationDate) {
413	        return (int) this.clinicService.findAllOwners().stream()
414	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
415	            .count();
416	    }
417	
418	    /**
419	     * Find the existing owners that live in the same household as the given values, i.e. those that
420	     * share both the last name and the address when each is compared case-insensitively with
421	     * collapsed whitespace.
422	     *
423	     * @param lastName the incoming owner's last name
424	     * @param address  the incoming owner's address
425	     * @return the matching existing owners (possibly empty)
426	     */
427	    private List<Owner> findHouseholdMembers(String lastName, String address) {
428	        String normalizedLastName = normalizeForComparison(lastName);
429	        String normalizedAddress = normalizeForComparison(address);
430	        return this.clinicService.findAllOwners().stream()
431	            .filter(existing -> normalizeForComparison(existing.getLastName()).equals(normalizedLastName)
432	                && normalizeForComparison(existing.getAddress()).equals(normalizedAddress))
433	            .toList();
434	    }
435	
436	    /**
437	     * Generate a stable shared household identifier for the given last name and address. The value is
438	     * derived deterministically from the normalized (case-insensitive, whitespace-collapsed) last name
439	     * and address, so every owner joining the same household resolves to the same identifier. It is the
440	     * first 12 upper-case hex characters of the SHA-256 digest of {@code <lastName>|<address>}.
441	     *
442	     * @param lastName the household's last name
443	     * @param address  the household's address
444	     * @return the stable household identifier
445	     */
446	    private String generateHouseholdId(String lastName, String address) {
447	        String key = normalizeForComparison(lastName) + "|" + normalizeForComparison(address);
448	        try {
449	            byte[] digest = MessageDigest.getInstance("SHA-256")
450	                .digest(key.getBytes(StandardCharsets.UTF_8));
451	            StringBuilder sb = new StringBuilder(digest.length * 2);
452	            for (byte b : digest) {
453	                sb.append(String.format("%02x", b));
454	            }
455	            return sb.substring(0, 12).toUpperCase(Locale.ROOT);
456	        } catch (java.security.NoSuchAlgorithmException e) {
457	            throw new IllegalStateException("SHA-256 not available", e);
458	        }
459	    }
460	
461	    /**
462	     * Normalize an owner address for storage: trim and collapse every internal run of whitespace to a
463	     * single space, upper-case the result and expand common street-type abbreviations token by token
464	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value normalizes
465	     * to the empty string. The result is the canonical form that is stored, returned and used for every
466	     * address comparison (household duplicate detection and the shared household id).
467	     *
468	     * @param address the raw address, may be {@code null}
469	     * @return the normalized address
470	     */
471	    private String normalizeAddress(String address) {
472	        if (address == null) {
473	            return "";
474	        }
475	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
476	        if (collapsed.isEmpty()) {
477	            return "";
478	        }
479	        String[] tokens = collapsed.split(" ");
480	        StringBuilder sb = new StringBuilder(collapsed.length());
481	        for (int i = 0; i < tokens.length; i++) {
482	            if (i > 0) {
483	                sb.append(' ');
484	            }
485	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
486	        }
487	        return sb.toString();
488	    }
489	
490	    /**
491	     * Normalize a value for identity comparison: trim, collapse every internal run of whitespace to a
492	     * single space and lower-case the result. A {@code null} value normalizes to the empty string.
493	     *
494	     * @param value the raw value, may be {@code null}
495	     * @return the normalized value
496	     */
497	    private String normalizeForComparison(String value) {
498	        if (value == null) {
499	            return "";
500	        }
501	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
502	    }
503	
504	    /**
505	     * Normalize an optional owner email address. A blank/absent value is treated as "not provided"
506	     * and returns {@code null}. When present, the value must be a syntactically valid address; if it
507	     * is not, an {@link InvalidRequestException} is thrown (mapped to 400 Bad Request). A valid value
508	     * is returned lower-cased.
509	     *
510	     * @param email the raw email from the request payload, may be {@code null}
511	     * @return the lower-cased email, or {@code null} when none was provided
512	     */
513	    private String normalizeEmail(String email) {
514	        if (!StringUtils.hasText(email)) {
515	            return null;
516	        }
517	        if (!EMAIL_PATTERN.matcher(email).matches()) {
518	            throw new InvalidRequestException(List.of("email"));
519	        }
520	        return email.toLowerCase(Locale.ROOT);
521	    }
522	
523	    /**
524	     * Validate an optional owner postcode. A blank/absent value is treated as "not provided" and
525	     * passes (postcode is optional). When present it must be exactly four digits, and when the owner's
526	     * city has a known region (Sydney->NSW, Melbourne->VIC, Brisbane->QLD) the postcode must fall within
527	     * that region's inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known
528	     * region accepts any 4-digit postcode. A violation throws an {@link InvalidRequestException} (mapped
529	     * to 400 Bad Request).
530	     *
531	     * @param city     the owner's city (used to resolve the region)
532	     * @param postcode the raw postcode from the request payload, may be {@code null}
533	     */
534	    private void validatePostcode(String city, String postcode) {
535	        if (!StringUtils.hasText(postcode)) {
536	            return;
537	        }
538	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
539	            throw new InvalidRequestException(List.of("postcode"));
540	        }
541	        String region = CITY_REGION.get(city);
542	        int[] range = region == null ? null : REGION_POSTCODE_RANGE.get(region);
543	        if (range != null) {
544	            int value = Integer.parseInt(postcode);
545	            if (value < range[0] || value > range[1]) {
546	                throw new InvalidRequestException(List.of("postcode"));
547	            }
548	        }
549	    }
550	
551	    /**
552	     * Normalize a telephone into E.164 form. Spaces, dashes and brackets are stripped. A value that
553	     * already carries a leading '+' keeps its country code; otherwise the default country code
554	     * ({@code +61}) is assumed and a single leading '0' is dropped from the national digits. The
555	     * result must be a '+' followed by 8 to 15 digits, otherwise an {@link InvalidRequestException}
556	     * is thrown (mapped to 400 Bad Request).
557	     *
558	     * @param telephone the raw telephone from the request payload
559	     * @return the E.164 string (e.g. {@code +61412345678})
560	     */
561	    private String normalizeTelephone(String telephone) {
562	        String cleaned = TELEPHONE_SEPARATORS.matcher(telephone).replaceAll("");
563	        String candidate;
564	        if (cleaned.startsWith("+")) {
565	            candidate = cleaned;
566	        } else {
567	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
568	            candidate = "+" + DEFAULT_COUNTRY_CODE + national;
569	        }
570	        if (!E164_PATTERN.matcher(candidate).matches()) {
571	            throw new InvalidRequestException(List.of("telephone"));
572	        }
573	        // For country codes with a known fixed national-number length, reject a candidate whose
574	        // national digits (everything after the '+' and the country code) do not match that length.
575	        String digits = candidate.substring(1);
576	        for (Map.Entry<String, Integer> entry : COUNTRY_NATIONAL_LENGTH.entrySet()) {
577	            String countryCode = entry.getKey();
578	            if (digits.startsWith(countryCode)) {
579	                int nationalLength = digits.length() - countryCode.length();
580	                if (nationalLength != entry.getValue()) {
581	                    throw new InvalidRequestException(List.of("telephone"));
582	                }
583	                break;
584	            }
585	        }
586	        return candidate;
587	    }
588	
589	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
590	    @Transactional
591	    @Override
592	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
593	        Owner owner = this.clinicService.findOwnerById(ownerId);
594	        if (owner == null) {
595	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
596	        }
597	        this.clinicService.deleteOwner(owner);
598	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
599	    }
600	
601	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
602	    @Override
603	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
604	        Owner owner = this.clinicService.findOwnerById(ownerId);
605	        if (owner == null) {
606	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
607	        }
608	        HttpHeaders headers = new HttpHeaders();
609	        Pet pet = petMapper.toPet(petFieldsDto);
610	        owner.setId(ownerId);
611	        pet.setOwner(owner);
612	        pet.getType().setName(null);
613	        this.clinicService.savePet(pet);
614	        PetDto petDto = petMapper.toPetDto(pet);
615	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
616	            .buildAndExpand(pet.getId()).toUri());
617	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
618	    }
619	
620	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
621	    @Override
622	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
623	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
624	        if (currentOwner != null) {
625	            Pet currentPet = this.clinicService.findPetById(petId);
626	            if (currentPet != null) {
627	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
628	                currentPet.setName(petFieldsDto.getName());
629	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
630	                this.clinicService.savePet(currentPet);
631	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
632	            }
633	        }
634	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
635	    }
636	
637	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
638	    @Override
639	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
640	        HttpHeaders headers = new HttpHeaders();
641	        Visit visit = visitMapper.toVisit(visitFieldsDto);
642	        Pet pet = new Pet();
643	        pet.setId(petId);
644	        visit.setPet(pet);
645	        this.clinicService.saveVisit(visit);
646	        VisitDto visitDto = visitMapper.toVisitDto(visit);
647	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
648	            .buildAndExpand(visit.getId()).toUri());
649	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
650	    }
651	
652	
653	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
654	    @Override
655	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
656	        Owner owner = this.clinicService.findOwnerById(ownerId);
657	        if (owner != null) {
658	            Pet pet = owner.getPet(petId);
659	            if (pet != null) {
660	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
661	            }
662	        }
663	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
664	    }
665	}
